# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor layer_norm_lastdim128(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("layer_norm_lastdim128", &layer_norm_lastdim128, "Fused LayerNorm over last dim=128 (CUDA float32)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// One block per row, 128 threads, each thread handles one element.
// Performs: out = (x - mean) * rsqrt(var + eps) * weight + bias
__global__ void layer_norm_lastdim128_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int rows,
    float eps
) {
    const int row = blockIdx.x;
    const int col = threadIdx.x; // 0..127
    if (row >= rows) return;

    const float* row_in = x + row * 128;
    float* row_out = out + row * 128;

    float val = row_in[col];

    // Warp-level reduction for sum and sum of squares
    // We have 128 threads = 4 warps
    __shared__ float smem[2 * 4]; // [sum_warp, sumsq_warp] for 4 warps

    float s = val;
    float sq = val * val;

    // Intra-warp reduction
    for (int offset = 16; offset > 0; offset >>= 1) {
        s  += __shfl_down_sync(0xffffffff, s,  offset);
        sq += __shfl_down_sync(0xffffffff, sq, offset);
    }

    int warp_id = col >> 5;  // col / 32
    int lane_id = col & 31;

    if (lane_id == 0) {
        smem[warp_id]     = s;
        smem[4 + warp_id] = sq;
    }
    __syncthreads();

    // Final reduction across 4 warps by first 4 threads
    float total_sum = 0.0f;
    float total_sumsq = 0.0f;
    if (col < 4) {
        total_sum   = smem[col];
        total_sumsq = smem[4 + col];
    }
    // reduce across first warp (only first 4 lanes active)
    for (int offset = 2; offset > 0; offset >>= 1) {
        total_sum   += __shfl_down_sync(0x0000000f, total_sum,   offset);
        total_sumsq += __shfl_down_sync(0x0000000f, total_sumsq, offset);
    }

    __shared__ float mean_s;
    __shared__ float rstd_s;
    if (col == 0) {
        float mean = total_sum / 128.0f;
        float var  = total_sumsq / 128.0f - mean * mean;
        mean_s = mean;
        rstd_s = rsqrtf(var + eps);
    }
    __syncthreads();

    row_out[col] = (val - mean_s) * rstd_s * weight[col] + bias[col];
}

torch::Tensor layer_norm_lastdim128(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous() && bias.is_contiguous(), "weight and bias must be contiguous");
    TORCH_CHECK(x.size(-1) == 128, "last dimension must be 128");

    int64_t rows = x.numel() / 128;
    auto out = torch::empty_like(x);

    dim3 grid(rows);
    dim3 block(128);

    layer_norm_lastdim128_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)rows,
        (float)eps
    );

    return out;
