                    def __init__(self, normalized_shape):
                        super().__init__()
                        self.weight = nn.Parameter(torch.ones(normalized_shape))
                        self.bias   = nn.Parameter(torch.zeros(normalized_shape))
                        self.eps    = 1e-5

                    def forward(self, x):
                        if (x.is_cuda and x.dtype == torch.float32
                                and x.is_contiguous()
                                and x.size(-1) == 128):
                            try:
                                return _stark_get_extension().layer_norm_lastdim128(
                                    x, self.weight, self.bias, self.eps
                                )
                            except Exception:
                                pass
                        return F.layer_norm(x, (self.weight.numel(),), self.weight, self.bias, self.eps)

                self.norm = _FastLayerNorm128(embed_dim)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Forward pass of the AttentionBlock.
                :param x: Input tensor of shape (B, C, H, W)
                :return: Output tensor of the same shape (B, C, H, W)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        B, C, H, W = x.shape
        # <<<END_IMPROVE>>>
