        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        x = x_tokens.transpose(1, 2).contiguous().view(B, C, H, W)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return x
        # <<<END_IMPROVE>>>

